// Passo 1: conferimos que veio uma lista de verdade.
function temNoCardapio(cardapio, item) {
  if (!Array.isArray(cardapio)) {
    throw new Error('cardapio precisa ser uma lista');
  }

  // Passo 2: includes já devolve o sim/não pedido.
  return cardapio.includes(item);
}

console.log(temNoCardapio(['pizza', 'suco', 'bolo'], 'suco')); // true
console.log(temNoCardapio(['pizza', 'suco', 'bolo'], 'lasanha')); // false
